/* Framework-free design handoff. All DOM strings from JSON are escaped. */
'use strict';
const $ = (s, root = document) => root.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const params = new URLSearchParams(location.search);
const sampleId = '14-rivington-st-EC2A3DU';
const labels = {confirmed:'Closure confirmed', probable:'Likely closure', possible:'Unverified closure', entity_change:'New company, same venue'};
const colours = {confirmed:'#c34d36', probable:'#c3963c', possible:'#8b9286', entity_change:'#365e48'};
const disclaimer = 'Signals from public records (Companies House, Google, FSA). Not an accusation or legal advice. Company changes can have ordinary reasons.';
let cases = [], sample, english, map, pins, tileFailures = 0;
let venueDetails = {by_place_id:{},by_case_listing:{}};
const path = (page, id) => `${page}.html?id=${encodeURIComponent(id)}`;
const badge = level => `<span class="badge ${Object.hasOwn(labels, level) ? level : 'possible'}">${esc(labels[level] || 'Unclear')}</span>`;
const source = (name, url) => url ? `<a class="source" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(name)} ↗</a>` : `<span class="source">${esc(name)}</span>`;
let CHECKED = '';  // date of the last verification run, from cases[].verified_at
const checked = () => CHECKED ? `<small>Checked ${CHECKED}</small>` : '';
const chURL = c => c.company_number && /^\d{8}$|^[A-Z]{2}\d{6}$/.test(c.company_number) ? `https://find-and-update.company-information.service.gov.uk/company/${c.company_number}` : null;
const googleURL = v => v.evidence?.[0] ? `https://www.google.com/maps/search/?api=1&query=venue&query_place_id=${encodeURIComponent(v.evidence[0])}` : null;
const dates = date => date ? new Intl.DateTimeFormat('en-GB',{month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(`${date}T00:00:00Z`)) : 'Unknown';
// Always give the period: "2 food companies at this address, 2017–2026".
const yearsOf = c => { const ys = (c.chain || []).flatMap(x => [x.opened, x.closed]).filter(Boolean).map(d => d.slice(0, 4)).sort(); return ys.length ? (ys[0] === ys[ys.length - 1] ? ys[0] : `${ys[0]}–${ys[ys.length - 1]}`) : ''; };
const countText = c => `${c.chain?.length || 0} food ${(c.chain?.length || 0) === 1 ? 'company' : 'companies'} at this address${yearsOf(c) ? `, ${yearsOf(c)}` : ''}`;
function toast(message) { $('#toast').textContent=message; $('#toast').classList.add('visible'); setTimeout(()=>$('#toast').classList.remove('visible'),3000); }
function verdict(item) {
 const v=item.verification || {};
 if (v.verdict==='closed_google') return /CLOSED_TEMPORARILY|closed temporarily|temporarily closed/i.test(v.note || '') ? ['Temporarily closed · Google','amber'] : ['Closed · Google','confirmed'];
 if(v.verdict==='operating_now') return ['Operating now · matched record','green'];
 if(v.verdict==='no_trace') return ['No venue trace found','possible'];
 return ['Trading status unclear','possible'];
}
function sourcesFor(c) {return `<div class="sources">${source('Companies House',chURL(c))}${source('Google',googleURL(c.verification || {}))}${checked()}</div>`;}
function mapMarkup(hero=false) {return `<div class="${hero?'hero-map':'map-panel'}"><div id="map" class="map" role="region" aria-label="Map of address cases in Shoreditch and Hackney"></div><div id="map-note" class="map-note" hidden>Street-map tiles are unavailable. Pins use real coordinates; use the address list for details.</div>${hero?`<div class="hero-caption"><div class="eyebrow" style="margin:0">An address. More than one story.</div><a href="${path('case',sampleId)}"><div><h3>14 Rivington Street</h3><span class="small muted">Two company histories. Questions worth asking.</span></div><span aria-hidden="true">↗</span></a></div>`:'<div class="map-legend"><span><i class="dot confirmed"></i>Closure confirmed</span><span><i class="dot probable"></i>Likely closure</span><span><i class="dot"></i>Unverified</span><span><i class="dot entity_change"></i>New company, same venue</span></div>'}</div>`;}
function initMap(data, hero=false) {
 if(!window.L){ $('#map').innerHTML='<div class="empty">Map unavailable. Explore the address list below.</div>'; return; }
 map=L.map('map',{scrollWheelZoom:false,zoomControl:!hero,attributionControl:true}).setView([51.5255,-.0795],hero?15:15);
 L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).on('tileerror',()=>{tileFailures++;if(tileFailures>2)$('#map-note').hidden=false;}).addTo(map);
 pins=L.layerGroup().addTo(map); updatePins(data);
}
function updatePins(data) {
 if(!pins)return; pins.clearLayers();
 for(const c of data){ const coords=c.location?.coordinates;if(!coords || !coords.every(Number.isFinite))continue;
 const marker=L.marker([coords[1],coords[0]],{icon:L.divIcon({className:'map-marker',html:`<div class="pin ${Object.hasOwn(labels,c.closure_level)?c.closure_level:'possible'}"></div>`,iconSize:[20,20],iconAnchor:[10,10]}),title:c.address,alt:c.address});
 marker.bindPopup(`<b>${esc(c.address)}</b><br>${esc(labels[c.closure_level] || 'Unclear')}<br><a href="${path('case',c.id)}">Open case file →</a>`).addTo(pins);
 }
}
function home(){
 $('#main').innerHTML=`<div class="wrap"><section class="hero"><div><p class="eyebrow">Local knowledge, before the big decision</p><h1>Before you sign,<br><em>know the story.</em></h1><p class="lead" id="home-lead">Who was here before you? What changed? Explore the evidence behind an address, before you sign the lease.</p><div class="mode-row"><div class="segmented" role="group" aria-label="Choose your mode"><button aria-pressed="true" data-mode="owner">I'm opening a venue</button><button aria-pressed="false" data-mode="worker">I'm taking a job</button></div><img class="hero-crumb" src="assets/crumb/crumb-point-left.webp" alt="" width="418" height="440"></div><form id="home-search"><label class="search-label" for="query">Address or venue name</label><div class="search-box"><input id="query" name="q" placeholder="Try 14 Rivington St" autocomplete="off"><button class="btn accent" type="submit">Investigate <span aria-hidden="true">↗</span></button></div></form><div class="examples"><span>Start with</span><a href="board.html?q=Pitfield">Pitfield St</a><a href="${path('case',sampleId)}">Rivington St</a><a href="board.html?q=Great%20Eastern">Great Eastern St</a></div><div class="sources" style="margin-top:24px">${source('Companies House')}${source('Google')}${source('FSA')}</div></div>${mapMarkup(true)}</section><section class="scenarios" aria-label="When people use it"><p class="eyebrow">When you would use it</p><div class="scenario-grid"><a class="scenario reveal" href="plan.html?concept=bakery&q=Hill%20Street%2C%20Richmond&r=500"><span class="badge">Opening a bakery</span><h3>You have found a unit on Hill Street, Richmond.</h3><p>Before the viewing, see the 16 bakeries within 500 m, what they charge, how well they are rated, and which food businesses closed nearby.</p><span class="text-link">See the competition →</span></a><a class="scenario reveal" href="case.html?id=57-pitfield-st-N16BU"><span class="badge">Signing a lease</span><h3>The agent says the last tenant on Pitfield Street “moved on”.</h3><p>Three food companies at 57 Pitfield Street in seven years. The venue still trades under a newer company. Ask the landlord why — and check the planning history first.</p><span class="text-link">Open the address history →</span></a><a class="scenario reveal" href="employer.html?q=Schnitzel%20Heaven"><span class="badge">Taking a job</span><h3>You have been offered shifts at a busy restaurant.</h3><p>See whether the company behind it was dissolved while the venue kept trading, what your shifts may look like, and what to ask before day one.</p><span class="text-link">Check the employer →</span></a></div></section></div>`;
 let mode='owner';document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>{mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('#home-lead').textContent=mode==='worker'?"Before you take the shift, check the company records behind the venue. Know what to ask your employer.":'Who was here before you? What changed? Explore the evidence behind an address, before you sign the lease.';$('#query').placeholder=mode==='worker'?'Try Schnitzel Heaven':'Try 14 Rivington St';}));
 $('#home-search').addEventListener('submit',e=>{e.preventDefault();location.href=`${mode==='owner'?'plan':'employer'}.html?q=${encodeURIComponent($('#query').value.trim())}`;});initMap(cases,true);
}
function tile(c){return `<article class="case-tile"><div class="tile-top">${badge(c.closure_level)}<span class="small muted">${c.chain?.length || 0} ${(c.chain?.length || 0) === 1 ? 'record' : 'records'}</span></div><h3><a href="${path('case',c.id)}">${esc(c.address.replace(/, London$/,''))}</a></h3><p>${esc(countText(c))}. ${c.now_here?.length?'Current venue records available.':'Current occupant not verified.'}</p>${(c.chain||[]).length?(()=>{const item=c.chain[c.chain.length-1],d=historicalVenue(item),v=item.verification||{},profile=foodProfile(d,d.name||item.name);return `<div class="tile-venue"><strong>${esc(d.name||item.name)}</strong>${/not recorded/i.test(profile.food)?'':`<p>${esc(profile.food)}</p>`}${[v.rating!=null?'★ '+esc(v.rating)+' / 5 · '+esc(v.rating_count??'—')+' reviews':'',esc(priceLabel(d)||'')].filter(Boolean).length?`<p class="quick-rating">${[v.rating!=null?'★ '+esc(v.rating)+' / 5 · '+esc(v.rating_count??'—')+' reviews':'',esc(priceLabel(d)||'')].filter(Boolean).join(' · ')}</p>`:''}<span class="provenance">Most recent company record · Google listing</span></div>`;})():''}<div class="sources">${source('Companies House')}${source(c.closure_level==='confirmed'?'Google':'Verification records')}</div><div class="tile-bottom"><span class="muted">${checked()}</span><a class="text-link" href="${path('case',c.id)}">Open case ↗</a></div></article>`;}
function matches(c,q){return [c.address,...(c.chain||[]).map(x=>x.name),...(c.now_here||[]).map(x=>x.name)].join(' ').toLowerCase().includes(q.toLowerCase());}
// Areas covered: Shoreditch & Hoxton (around Encode Hub) and Richmond & St Margarets.
const AREA_VIEW={shoreditch:{label:'Shoreditch & Hoxton',center:[51.5265,-0.0815],zoom:15},richmond:{label:'Richmond & St Margarets',center:[51.4593,-0.3109],zoom:14}};
let boardArea=AREA_VIEW[params.get('area')]?params.get('area'):'shoreditch';
function board(){
 $('#main').innerHTML=`<div class="wrap"><header class="page-heading"><div><p class="eyebrow">The neighbourhood, with a little more context</p><h1>Every address has a past.</h1><p>Follow the records. Find the questions worth asking.</p></div><div class="segmented" role="group" aria-label="Area">${Object.entries(AREA_VIEW).map(([k,a])=>`<button data-area="${k}" aria-pressed="${k===boardArea}">${a.label}</button>`).join('')}</div></header><div class="board-controls"><div class="filter-group" role="group" aria-label="Filter evidence level">${[['all','All addresses'],['confirmed','Closure confirmed'],['probable','Likely closure'],['possible','Unverified'],['entity_change','New company, same venue']].map(([key,label])=>`<button data-filter="${key}" aria-pressed="${key==='all'}">${label}</button>`).join('')}</div><label><span class="skip">Search address or venue</span><input id="board-query" class="compact-search" placeholder="Search address or venue" value="${esc(params.get('q')||'')}"></label></div><div class="board-grid">${mapMarkup()}<div><div class="list-heading"><span id="result-count" role="status" aria-live="polite"></span><span class="muted">Evidence first</span></div><div class="case-list" id="case-list"></div></div></div></div>`;
 initMap(cases);map?.setView(AREA_VIEW[boardArea].center,AREA_VIEW[boardArea].zoom);let filter='all';function render(){const data=cases.filter(c=>(c.area||'shoreditch')===boardArea&&(filter==='all'||c.closure_level===filter)&&matches(c,$('#board-query').value.trim())).sort((a,b)=>(a.closure_level==='confirmed'?-1:0)-(b.closure_level==='confirmed'?-1:0));$('#result-count').textContent=`${data.length} ${data.length===1?'address':'addresses'} in this view`;$('#case-list').innerHTML=data.length?data.map(tile).join(''):'<div class="empty"><h2>No matching cases yet.</h2><p>Try a shorter street or venue name, or another evidence filter.</p></div>';updatePins(data);}
 document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));render();}));$('#board-query').addEventListener('input',render);document.querySelectorAll('[data-area]').forEach(b=>b.addEventListener('click',()=>{boardArea=b.dataset.area;document.querySelectorAll('[data-area]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));map?.setView(AREA_VIEW[boardArea].center,AREA_VIEW[boardArea].zoom);const u=new URL(location.href);u.searchParams.set('area',boardArea);history.replaceState(null,'',u);render();}));render();
}
function getCase(){const id=params.get('id')||sampleId;return cases.find(c=>c.id===id) || (id===sampleId?sample:null);}
function analysisFor(c){return c.analysis?.headline && !/[А-Яа-яЁё]/.test(c.analysis.headline) ? c.analysis : (c.id===sampleId?english:null);}
function historicalVenue(item) {
 const id=(item.verification?.evidence||[]).find(x=>typeof x==='string');
 return venueDetails.by_place_id?.[id] || {};
}
function foodProfile(detail, name='') {
 const types=[detail.primary_type,...(detail.types||[])].filter(Boolean);
 const cuisines={japanese_restaurant:'Japanese',korean_restaurant:'Korean',italian_restaurant:'Italian',greek_restaurant:'Greek',indian_restaurant:'Indian',chinese_restaurant:'Chinese',thai_restaurant:'Thai',vietnamese_restaurant:'Vietnamese',turkish_restaurant:'Turkish',mexican_restaurant:'Mexican',french_restaurant:'French',british_restaurant:'British',mediterranean_restaurant:'Mediterranean',lebanese_restaurant:'Lebanese',vegan_restaurant:'Vegan',vegetarian_restaurant:'Vegetarian'};
 const offers={steak_house:'Steaks',chicken_restaurant:'Chicken',chicken_wings_restaurant:'Chicken wings',ramen_restaurant:'Ramen',pizza_restaurant:'Pizza',gyro_restaurant:'Gyros',hamburger_restaurant:'Burgers',sushi_restaurant:'Sushi',sandwich_shop:'Sandwiches',bakery:'Baked goods',coffee_shop:'Coffee'};
 let format=types.includes('coffee_shop')?'Coffee shop':types.includes('bakery')?'Bakery':types.includes('cafe')?'Café':types.includes('fast_food_restaurant')?'Fast food':types.some(x=>x==='restaurant'||x.endsWith('_restaurant')||x==='steak_house')?'Restaurant':types.includes('bar')?'Bar':'Format not recorded';
 const food=[...new Set(types.filter(x=>cuisines[x]).slice(0,1).map(x=>cuisines[x]).concat(types.filter(x=>offers[x]).slice(0,2).map(x=>offers[x])))];
 if(!food.length && /Korean Fried Chicken & Ramen/i.test(name))return {format:'Format not recorded',food:'Korean fried chicken & ramen',basis:'Offer described in Google listing name'};
 return {format,food:food.join(' · ')||'Cuisine / menu not recorded',basis:types.length?'Google listing categories · not a verified menu':''};
}
function priceLabel(detail) {
 const range=detail.price_range, start=range?.startPrice, end=range?.endPrice;
 const money=p=>p && p.units!=null ? `${p.currencyCode==='GBP'?'£':(p.currencyCode||'')+' '}${Number(p.units)+(Number(p.nanos||0)/1e9)}`:null;
 const a=money(start),b=money(end); if(a&&b)return `${a}–${b}`;if(a)return `From ${a}`;if(b)return `Up to ${b}`;
 return {PRICE_LEVEL_FREE:'Free',PRICE_LEVEL_INEXPENSIVE:'£ · Inexpensive',PRICE_LEVEL_MODERATE:'££ · Moderate',PRICE_LEVEL_EXPENSIVE:'£££ · Expensive',PRICE_LEVEL_VERY_EXPENSIVE:'££££ · Premium'}[detail.price_level]||null;
}
function venueMetrics({rating,count,hygiene,hygieneDate,price}) {
 // Only the tiles we have data for; nothing at all when there is no data.
 const hasH=hygiene!==undefined && hygiene!==null && /^\d$/.test(String(hygiene)), tiles=[];
 if(rating!=null) tiles.push(`<div class="venue-metric google"><span class="metric-label">Google reviews</span><strong><span class="star" aria-hidden="true">★</span> ${esc(rating)}<small>/ 5</small></strong><span class="metric-caption">${count!=null?`${esc(count.toLocaleString('en-GB'))} reviews`:''}</span></div>`);
 if(hasH) tiles.push(`<div class="venue-metric hygiene ${Number(hygiene)>=4?'scored':Number(hygiene)>=2?'hygiene-amber':'hygiene-red'}"><span class="metric-label">Food hygiene · FSA</span><strong>${esc(hygiene)}<small>/ 5</small></strong><span class="metric-caption">${hygieneDate?`Rated ${esc(hygieneDate)}`:''}</span></div>`);
 if(price) tiles.push(`<div class="venue-metric price"><span class="metric-label">Price · Google</span><strong>${esc(price)}</strong><span class="metric-caption">Listed price range</span></div>`);
 return tiles.length?`<div class="venue-metrics">${tiles.join('')}</div>`:'';
}
function venueIdentity(item) {
 const detail=historicalVenue(item), name=detail.name||item.name, profile=foodProfile(detail,name), v=item.verification||{};
 const rating=v.rating??detail.rating, price=priceLabel(detail), known=!/not recorded/i.test(profile.format+profile.food);
 // Closed venues usually leave no ratings behind: one honest line instead of three empty tiles.
 return `<div class="venue-identity"><h3>${esc(name)}</h3>${known?`<p class="venue-concept">${esc(profile.format)} <span aria-hidden="true">/</span> ${esc(profile.food)}</p>`:''}</div>${venueMetrics({rating,count:v.rating_count??detail.rating_count,price})}<p class="legal-name">Company record: ${esc(item.name)}</p>`;
}
function premisesPanel(c) {
 return `<section class="panel premises-panel" id="premises"><p class="eyebrow">02 / Before the lease</p><h2>Will the space work for your concept?</h2><p class="panel-intro">Planning use, installed extraction and suitability for your equipment are three different checks. A previous restaurant is not proof of permission for your proposal.</p><div class="premises-status"><div><span class="metric-label">Lawful use class</span><strong>Not verified</strong><small>No decision notice supplied</small></div><div><span class="metric-label">Extraction installed</span><strong>Not verified</strong><small>No site survey or as-built plan</small></div><div><span class="metric-label">Suitable for your menu</span><strong>Assessment needed</strong><small>Equipment and production load matter</small></div></div><label class="search-label" for="concept-check">What are you planning?</label><select id="concept-check"><option value="bakery">Patisserie / bakery with on-site baking</option><option value="coffee">Coffee shop / bought-in pastries</option><option value="kitchen">Restaurant / frying and hot cooking</option></select><div id="concept-questions" aria-live="polite"></div><details><summary>Class A or E — what does it mean?</summary><p>In England, former A1 shops and A3 cafés/restaurants generally moved into Class E in September 2020. Hot-food takeaways are generally sui generis. Bakery production needs its own use assessment: the balance of retail, on-site consumption and production matters.</p><p style="margin-top:10px">Check the lawful use and planning conditions for the exact unit. Class E does not establish permission for a duct, a landlord’s consent, or the suitability of a ventilation system.</p><div class="sources">${source('GOV.UK · use classes','https://www.gov.uk/guidance/when-is-permission-required')}${source('Planning Portal','https://www.planningportal.co.uk/permission/common-projects/shops/i-want-to-convert-a-shop-to-a-cafe-public-house-or-takeaway/')}</div></details><details><summary>What documents should I ask for?</summary><ul><li>Planning decision notices, approved drawings and any restrictions on cooking, hours, noise or odour.</li><li>Landlord’s written permitted use and consent for alterations, roof access and duct routes.</li><li>Extraction specification, discharge route, replacement-air provision, and commissioning / maintenance records.</li><li>A ventilation assessment against the actual ovens, fryers, fuel, menu and hours proposed.</li></ul><p>General ventilation and cooking extraction are not interchangeable. The presence of a canopy, electric ovens or a high food-hygiene rating does not establish suitability.</p><div class="sources">${source('HSE · kitchen ventilation','https://www.hse.gov.uk/pubns/cais10.htm')}${source('Hackney · planning register','https://www.hackney.gov.uk/planning-and-building/view-and-comment-planning-applications')}</div></details><p class="disclaimer" style="margin-top:18px">General England guidance checked 24 October 2026. This is a due-diligence checklist, not an address-specific planning or engineering assessment. No planning history or extraction record has been verified for ${esc(c.address)}.</p></section>`;
}
function initPremises(){
 const select=$('#concept-check');if(!select)return;
 const options={bakery:{title:'On-site baking needs an equipment-led assessment.',text:'Specify the ovens, baking volume, steam, heat and preparation processes. Electric equipment does not by itself establish that extraction is unnecessary.',questions:['Can the proposed ovens discharge heat and steam through the approved system?','Is sufficient replacement air available at peak production?','Can any required ductwork be installed, and are route, noise and odour conditions acceptable?']},coffee:{title:'Bought-in pastries and on-site production are different proposals.',text:'Describe coffee equipment, dishwashing, reheating and any future baking. Do not assume today’s light preparation setup covers tomorrow’s production kitchen.',questions:['What equipment and food preparation does the current permission cover?','Is ventilation sufficient for heat and steam from all appliances?','Would adding ovens or hot cooking require a new assessment or consent?']},kitchen:{title:'Assess the extraction for the actual cooking load.',text:'Frying, grilling and hot cooking can generate grease, fumes, odour and heat. Have a competent specialist assess the required extraction and safe discharge.',questions:['Does the system cover the proposed appliances, fuel and peak cooking load?','Are duct discharge, odour and noise controls acceptable for neighbouring properties?','Are commissioning, cleaning and maintenance records available?']}};
 function render(){const item=options[select.value];$('#concept-questions').innerHTML=`<div class="concept-guidance"><h3>${item.title}</h3><p>${item.text}</p><ul>${item.questions.map(x=>`<li>${x}</li>`).join('')}</ul><p class="small"><strong>Result: site assessment needed.</strong> Selecting a concept does not verify the premises.</p></div>`;}
 select.addEventListener('change',render);render();
}

function timeline(c){return `<ol class="timeline">${(c.chain||[]).map(item=>{const [label,level]=verdict(item);return `<li><div class="timeline-top"><span class="date">${esc(dates(item.opened))} — ${esc(dates(item.closed))}</span><span class="badge ${level}">${label}</span></div>${venueIdentity(item)}<p>${item.months==null?'Company lifespan unavailable':`Company existed ${esc(item.months)} months (not the same as trading)`}</p>${sourcesFor(item)}${/CLOSED_TEMPORARILY|closed temporarily|temporarily closed/i.test(item.verification?.note||'')?'<p class="muted">Temporary closure is not evidence of permanent closure.</p>':''}</li>`;}).join('')}</ol>`;}

function context(c){const ctx=c.context || {};return `<section class="panel"><p class="eyebrow">Around this address</p><h2>The local picture</h2><div class="metric"><strong>${esc(ctx.venues_within_150m_FSA??'—')}</strong><p>FSA-listed venues within 150 m</p><div class="sources">${source('FSA')}${checked()}</div></div><div class="metric"><strong>${esc(ctx.nearest_station?.m??'—')} <small>m</small></strong><p>${esc(ctx.nearest_station?.name||'Nearest station')}</p><div class="sources">${source('Dataset · station distance')}${checked()}</div></div><div class="metric"><strong>${esc(c.dist_hub_m??'—')} <small>m</small></strong><p>${c.area==='richmond'?'From the centre of Richmond & St Margarets':'From Encode Hub'}</p><div class="sources">${source('Dataset · hub distance')}${checked()}</div></div></section>`;}
function nowHere(c){
 const rows=[]; const key=n=>n.name.toLowerCase().replace(/[^a-z0-9]/g,'');
 for(const n of c.now_here||[]){const existing=rows.find(r=>key(r)===key(n));if(existing && existing.src!==n.src){existing.parts.push(n);}else rows.push({...n,parts:[n]});}
 return `<section class="panel venue-list"><p class="eyebrow">A more recent chapter</p><h2>At and around this address</h2><p class="panel-intro">Nearby listings, not proof of the current tenant. Scores belong to the named venue and may not describe a past operator.</p>${rows.map(row=>{const fsa=row.parts.find(x=>x.src==='FSA'),google=row.parts.find(x=>x.src==='Google');const detail=row.parts.map(n=>venueDetails.by_case_listing?.[c.id+'|'+n.src+'|'+n.name]).find(Boolean)||{};const profile=foodProfile(detail,row.name);return `<article class="now-row"><h3>${esc(detail.name||row.name)}</h3><p class="venue-concept">${[profile.format,profile.food].filter(x=>x&&!/not recorded/i.test(x)).map(esc).join(' / ')}</p><p class="provenance">${esc(profile.basis)}</p>${detail.address?`<p class="listing-address">${esc(detail.address)}</p>`:''}${venueMetrics({rating:google?.rating??detail.rating,count:google?.n??detail.rating_count,hygiene:fsa?.hygiene,hygieneDate:fsa?.rating_date,price:priceLabel({...detail,price_range:google?.price_range??detail.price_range})})}<div class="sources">${fsa?source('FSA'):''}${google||detail.place_id?source('Google',detail.place_id?'https://www.google.com/maps/search/?api=1&query=venue&query_place_id='+encodeURIComponent(detail.place_id):null):''}<small>Source dates may differ</small></div></article>`;}).join('')||'<p class="muted small">No current listing supplied.</p>'}</section>`;
}

const CONFIDENCE = {high: 'we are fairly sure', medium: 'plausible', low: 'a weak guess'};
// Today's status of the venue, separate from the address history: the labels above describe past companies.
function venueToday(c) {
  const v = (c.chain || []).map(x => x.verification || {});
  if (v.some(x => x.verdict === 'operating_now')) return 'Trading under a newer company';
  const g = [...v].reverse().find(x => x.verdict === 'closed_google');
  if (g) return /temporar/i.test(g.note || '') ? 'Temporarily closed (Google)' : 'Closed (Google)';
  return 'Unknown: check in person';
}
function caseSummary(c, a) {
  const top = a?.hypotheses?.[0];
  return `<section class="panel summary"><p class="eyebrow">In short</p><h2>${esc(a?.headline || countText(c))}</h2>
  <div class="metric"><strong style="font-size:1.1rem">${esc(venueToday(c))}</strong><p>Venue today</p></div>
  ${top ? `<div class="counter"><b>Most likely reason · ${esc(CONFIDENCE[top.confidence] || top.confidence)}</b>${esc(top.reason)}<br><br><b>What argues against it</b>${esc(top.counter_argument)}</div>` : ''}
  <h3 style="margin-top:18px">Ask the landlord</h3><ul class="small"><li>Why did the last tenant leave, and when?</li><li>What does the planning permission allow? Ask for the decision notice.</li><li>Is extraction installed and approved for cooking? Ask for the plans.</li></ul>
  <p class="disclaimer">Facts come from public records${CHECKED ? `, checked ${CHECKED}` : ''}. Reasons are our best guesses and labelled that way. Company dates are paperwork, not opening hours.</p></section>`;
}
