 if(gone)$('#selected-employer').insertAdjacentHTML('afterbegin',`<section class="status-panel"><div class="traffic" aria-label="Amber: needs verification"><span></span><span class="on"></span><span></span></div><h2>Check who your employer is on paper.</h2><p>Companies House lists <strong>${esc(gone.name)}</strong> as dissolved in ${esc(dates(gone.closed))}. ${esc(v.name)} is still trading. This can have ordinary reasons, but your employer is the company named on your contract.</p></section>`);
